/// <summary>
/// National report execution class
/// </summary>
public class METNature3040ReportExecute_National extends METNature3040ReportExecute
{
}

Method.Source:
/// <summary>
/// generate national report file name
/// </summary>
/// <param name = "_contract">contract</param>
/// <returns>filename</returns>
public Filename generateFileName(METNature3040ReportContract    _contract)
{
    if (_contract.parmMETNat3040() == METNAT3040::NAT30)
    {
        fileName = strFmt("@MET:NationalNat30Report", _contract.parmNat30Number(),DateTimeUtil::date(_contract.parmFromDate()), DateTimeUtil::date(_contract.parmToDate()));
        fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
    }
    else if (_contract.parmMETNat3040() == METNAT3040::NAT40)
    {
        fileName = strFmt("@MET:NationalNat40Report", _contract.parmNat30Number(),DateTimeUtil::date(_contract.parmFromDate()), DateTimeUtil::date(_contract.parmToDate()));
        fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
    }
    return fileName;
}

/// <summary>
/// National report status update
/// </summary>
/// <param name = "_reportRunContract">contract</param>
public void updateReportStatus(METNature3040ReportContract  _reportRunContract)
{
    METNature3040ReportsTable               metNature3040ReportsTable;

    update_recordset metNature3040ReportsTable
        setting NationalReportGenerated = NoYes::Yes
        where metNature3040ReportsTable.Nat3040ReportNumber == _reportRunContract.parmNat30Number();
}

/// <summary>
/// National report execution
/// </summary>
public void executeReport()
{
    METNature3040ReportsTable               metNature3040ReportsTable;
    METNAT3040                              metNat3040;
    METNature3040ReportContract             reportRunContract;
    METReportRunHistory                     lastSucessfulReportRun;
    TransDateTime                           successfulRunDate;

    super();

    select firstonly RecId from METNature3040ReportsTable
        where METNature3040ReportsTable.Nat3040ReportNumber == contract.parmNat30Number() && 
              METNature3040ReportsTable.SiteSpecificReportGenerated == NoYes::No;

    if (!metNature3040ReportsTable.RecId)
    {
        metNature3040ReportsTable = null;
        select firstonly RecId from METNature3040ReportsTable
            where METNature3040ReportsTable.Nat3040ReportNumber == contract.parmNat30Number() &&
              METNature3040ReportsTable.NationalReportGenerated == NoYes::No;

        if (metNature3040ReportsTable.RecId)
        {
            try
            {
                ttsbegin;

                reportRunContract = contract;

                reportRunContract.parmBondNumber("");
                reportRunContract.parmSite("");
                reportRunContract.parmSiteName("");

                metNature3040ReportsTable = null;
                select firstonly FromDateTime from metNature3040ReportsTable order by FromDateTime
                where metNature3040ReportsTable.Nat3040ReportNumber == contract.parmNat30Number();

                contract.parmFromDate(metNature3040ReportsTable.FromDateTime);

                metNature3040ReportsTable = null;

                select firstonly ToDateTime from metNature3040ReportsTable order by ToDateTime desc
                where metNature3040ReportsTable.Nat3040ReportNumber == contract.parmNat30Number();

                contract.parmToDate(metNature3040ReportsTable.ToDateTime);
                contract.parmLastRunDateTime(contract.parmToDate());

                this.generateReportAndSaveToSharePoint(reportRunContract);

                this.updateReportStatus(reportRunContract);
                ttscommit;
            }
            catch
            {
                ttsabort;
                error("@MET:SharepointError");
            }
        }
    }
}
